-- +goose Up
-- Seeds the vendor-neutral (generic) OCPP 1.6J core schemas, sourced from the
-- official OCA OCPP 1.6 JSON schema set. These act as the fallback used when no
-- vendor- or model-specific schema has been submitted for an action.
ON CONFLICT ON CONSTRAINT schemas_lookup_unique DO NOTHING;

-- +goose Down
DELETE FROM schemas
WHERE ocpp_version = '1.6' AND vendor IS NULL AND model IS NULL AND action IN (
    'Authorize',
    'BootNotification',
    'CancelReservation',
    'ChangeAvailability',
    'ChangeConfiguration',
    'ClearCache',
    'ClearChargingProfile',
    'DataTransfer',
    'DiagnosticsStatusNotification',
    'FirmwareStatusNotification',
    'GetCompositeSchedule',
    'GetConfiguration',
    'GetDiagnostics',
    'GetLocalListVersion',
    'Heartbeat',
    'MeterValues',
    'RemoteStartTransaction',
    'RemoteStopTransaction',
    'ReserveNow',
    'Reset',
    'SendLocalList',
    'SetChargingProfile',
    'StartTransaction',
    'StatusNotification',
    'StopTransaction',
    'TriggerMessage',
    'UnlockConnector',
    'UpdateFirmware'
);
